import React from "react"; // Don't forget to import React
import NavigationLink from "./Link/NavigationLink";
import { NavigationLinkInfo } from "./Link/NavigationLinkInfo"; // Correct import for type

const Navigation = () => {
  // Correct way to declare and initialize an array of objects
  // The type annotation goes after the variable name
  const linksInfo: NavigationLinkInfo[] = [
    { labelText: "Home", href: "/", isActive: true },
    { labelText: "About", href: "/about" },
    { labelText: "Contact", href: "/contact" },
  ];

  return (
    <nav className="navigation-container">
      {/* Now you can map over linksInfo to render NavigationLink components */}
      {linksInfo.map((link, index) => (
        <NavigationLink
          key={link.href || index} // Use a stable unique key. href is often good if unique.
          labelText={link.labelText}
          href={link.href}
          isActive={link.isActive} // Pass isActive prop
        />
      ))}
    </nav>
  );
};

export default Navigation;
